//! Byte-level string inflection library (black-box port).
//!
//! All transformations operate on ASCII bytes and preserve any non-ASCII
//! (e.g. UTF-8 continuation) bytes unchanged.

pub mod pluralize;
pub mod text;

//! Pluralization and singularization rules.

/// Exact, case-sensitive uncountable words.
const UNCOUNTABLES: [&str; 10] = [
    "equipment",
    "information",
    "rice",
    "money",
    "species",
    "series",
    "fish",
    "sheep",
    "jeans",
    "police",
];

fn is_uncountable(word: &str) -> bool {
    UNCOUNTABLES.iter().any(|u| *u == word)
}

fn replace_suffix(word: &str, from: &str, to: &str) -> String {
    let mut s = String::with_capacity(word.len() - from.len() + to.len());
    s.push_str(&word[..word.len() - from.len()]);
    s.push_str(to);
    s
}

fn strip_last(word: &str, n: usize) -> String {
    word[..word.len() - n].to_string()
}

/// Append ASCII `s`, unless empty or an exact uncountable.
pub fn pluralize(word: &str) -> String {
    if word.is_empty() || is_uncountable(word) {
        return word.to_string();
    }
    let mut s = String::with_capacity(word.len() + 1);
    s.push_str(word);
    s.push('s');
    s
}

/// Singularize via first matching case-sensitive lowercase suffix rule.
pub fn singularize(word: &str) -> String {
    if word.is_empty() || is_uncountable(word) {
        return word.to_string();
    }
    let ends = |suf: &str| word.ends_with(suf);

    if ends("quizzes") {
        return replace_suffix(word, "quizzes", "quiz");
    }
    if ends("matrices") {
        return replace_suffix(word, "matrices", "matrix");
    }
    if ends("vertices") {
        return replace_suffix(word, "vertices", "vertex");
    }
    if ends("indices") {
        return replace_suffix(word, "indices", "index");
    }
    if ends("aliases") {
        return strip_last(word, 2);
    }
    if ends("statuses") {
        return strip_last(word, 2);
    }
    if ends("crises") {
        return replace_suffix(word, "es", "is");
    }
    if ends("axes") {
        return replace_suffix(word, "es", "is");
    }
    if ends("testes") {
        return replace_suffix(word, "es", "is");
    }
    if ends("oes") {
        return replace_suffix(word, "oes", "o");
    }
    if ends("buses") {
        return replace_suffix(word, "buses", "bus");
    }
    if ends("xes") || ends("ches") || ends("sses") || ends("shes") {
        return strip_last(word, 2);
    }
    if ends("ies") {
        // consonant/qu + ies -> consonant/qu + y
        if ends("quies") {
            return replace_suffix(word, "ies", "y");
        }
        let b = word.as_bytes();
        let prev = b[b.len() - 3];
        if prev.is_ascii_alphabetic() && !matches!(prev, b'a' | b'e' | b'i' | b'o' | b'u') {
            return replace_suffix(word, "ies", "y");
        }
        // vowel + ies: only strip the final s
        return strip_last(word, 1);
    }
    if ends("ves") {
        let b = word.as_bytes();
        let prev = if b.len() >= 4 { b[b.len() - 4] } else { 0 };
        if prev != b'f' {
            return replace_suffix(word, "ves", "fe");
        }
        // "fves" falls through to later rules
    }
    if ends("analyses") {
        // quirk: analyses -> analyasis
        return replace_suffix(word, "analyses", "analyasis");
    }
    for (from, to) in [
        ("bases", "basis"),
        ("diagnoses", "diagnosis"),
        ("parentheses", "parenthesis"),
        ("prognoses", "prognosis"),
        ("synopses", "synopsis"),
        ("theses", "thesis"),
    ] {
        if ends(from) {
            return replace_suffix(word, from, to);
        }
    }
    if ends("news") {
        return word.to_string();
    }
    if ends("ss") {
        return strip_last(word, 1);
    }
    if word.as_bytes()[word.len() - 1] == b's' {
        return strip_last(word, 1);
    }
    word.to_string()
}

//! Byte-level ASCII case and separator transformations.

/// Insert `_` before each ASCII uppercase byte (unless at byte index 0) and
/// lowercase it; preserve everything else.
pub fn underscore(s: &str) -> String {
    let mut out = Vec::with_capacity(s.len());
    for (i, &b) in s.as_bytes().iter().enumerate() {
        if b.is_ascii_uppercase() {
            if i != 0 {
                out.push(b'_');
            }
            out.push(b.to_ascii_lowercase());
        } else {
            out.push(b);
        }
    }
    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
}

/// Shared camelize core: remove underscores and ASCII-uppercase the byte
/// immediately after each underscore. A non-letter byte after an underscore
/// still consumes the pending capitalize.
fn camel(s: &str, upper_first: bool) -> String {
    let mut out = Vec::with_capacity(s.len());
    let mut cap = upper_first;
    for &b in s.as_bytes() {
        if b == b'_' {
            cap = true;
            continue;
        }
        if cap {
            out.push(b.to_ascii_uppercase());
            cap = false;
        } else {
            out.push(b);
        }
    }
    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
}

/// Lower-camelize: byte 0 keeps its case.
pub fn camelize(s: &str) -> String {
    camel(s, false)
}

/// Upper-camelize the entire input (byte 0 is ASCII-uppercased).
pub fn classify(s: &str) -> String {
    camel(s, true)
}

/// underscore(input), then append `s`.
pub fn tableize(s: &str) -> String {
    let mut out = underscore(s);
    out.push('s');
    out
}

/// Replace underscores with spaces; ASCII-uppercase only the first byte;
/// preserve all other case. Does not strip `_id`.
pub fn humanize(s: &str) -> String {
    let mut out: Vec<u8> = s
        .bytes()
        .map(|b| if b == b'_' { b' ' } else { b })
        .collect();
    if let Some(first) = out.first_mut() {
        *first = first.to_ascii_uppercase();
    }
    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
}

/// Split on literal spaces only: uppercase the first byte of each segment,
/// lowercase all remaining bytes; spaces preserved exactly.
pub fn titleize(s: &str) -> String {
    let mut out = Vec::with_capacity(s.len());
    let mut start = true;
    for &b in s.as_bytes() {
        if b == b' ' {
            out.push(b);
            start = true;
        } else if start {
            out.push(b.to_ascii_uppercase());
            start = false;
        } else {
            out.push(b.to_ascii_lowercase());
        }
    }
    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
}

/// Underscores become hyphens; nothing else changes.
pub fn dasherize(s: &str) -> String {
    s.bytes()
        .map(|b| if b == b'_' { b'-' } else { b })
        .map(char::from)
        .collect()
}

/// Spaces become hyphens one-for-one; ASCII alphanumerics are kept and
/// ASCII-uppercased lowercased; every other byte is deleted.
pub fn parameterize(s: &str) -> String {
    let mut out = Vec::with_capacity(s.len());
    for &b in s.as_bytes() {
        if b == b' ' {
            out.push(b'-');
        } else if b.is_ascii_alphanumeric() {
            out.push(b.to_ascii_lowercase());
        }
    }
    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
}

/// ASCII byte-wise upcase.
pub fn upcase(s: &str) -> String {
    s.bytes().map(|b| b.to_ascii_uppercase()).map(char::from).collect()
}

/// ASCII byte-wise downcase.
pub fn downcase(s: &str) -> String {
    s.bytes().map(|b| b.to_ascii_lowercase()).map(char::from).collect()
}

/// Lowercase all bytes, then uppercase the first byte only.
pub fn capitalize(s: &str) -> String {
    let mut out: Vec<u8> = s.bytes().map(|b| b.to_ascii_lowercase()).collect();
    if let Some(first) = out.first_mut() {
        *first = first.to_ascii_uppercase();
    }
    String::from_utf8(out).expect("ASCII transforms preserve UTF-8")
}

