//! Entry binary for the test13 harness.
//!
//! Includes the library modules directly via `#[path]` so that both
//! `cargo build --release` (via the `[[bin]]` target) and a plain
//! `rustc --edition=2021 test13.rs` invocation work from the project root.

#[path = "src/pluralize.rs"]
mod pluralize;
#[path = "src/text.rs"]
mod text;

use std::env;

fn main() {
    let mut args = env::args();
    let _ = args.next(); // program name
    let word = match args.next() {
        Some(w) => w,
        None => return, // no argv[1]: print nothing, exit 0
    };
    // Extra args are ignored; argv[1] is treated literally.

    let lines = [
        pluralize::pluralize(&word),
        pluralize::singularize(&format!("{word}s")),
        text::camelize(&format!("test_{word}")),
        text::underscore(&format!("Test{word}")),
        text::classify(&format!("{word}_table")),
        text::tableize(&format!("{word}Class")),
        text::humanize(&format!("{word}_id")),
        text::titleize(&word),
        text::dasherize(&word),
        text::parameterize(&format!("The {word} Test")),
        text::upcase(&word),
        text::downcase(&word),
        text::capitalize(&word),
    ];

    let mut out = String::new();
    for line in &lines {
        out.push_str(line);
        out.push('\n');
    }
    print!("{out}");
}

